const {monthlyTotals,validMonth,validExpense,validAd,repeatExpenses}=Educa;
const expenseCategories={marketing:'Serviço de marketing',courses:'Pacote mensal de cursos',other:'Outro gasto'},expenseTypes={fixed:'Fixo',variable:'Variável'};
const monthLabel=m=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-01T12:00:00Z'));
function renderFinance(){
 const section=$('#finance-section');section.hidden=!['overview','expenses','ads'].includes(tab);if(section.hidden)return;
 const summary=monthlyTotals(state,financeMonth);
 const expenses=state.expenses.filter(r=>r.month===financeMonth),ads=state.adSpends.filter(r=>r.date.slice(0,7)===financeMonth).sort((a,b)=>b.date.localeCompare(a.date));
 const totalExpenses=summary.fixed+summary.variable;
 const overviewCards=[['Vendas do mês',summary.gross,`${summary.count} venda(s) pela data do cadastro da venda`],['Gastos mensais',totalExpenses,`Fixos: ${money(summary.fixed)} • Variáveis: ${money(summary.variable)}`],['Tráfego pago',summary.ads,`${ads.length} aporte(s) em anúncios`],['Resultado final do mês',summary.net,`Após custos e ${summary.taxRate.toLocaleString('pt-BR')}% de imposto`]];
 const cards=tab==='overview'?overviewCards:tab==='expenses'?[['Total de gastos mensais',totalExpenses,`Fixos: ${money(summary.fixed)} • Variáveis: ${money(summary.variable)}`]]:[['Total de tráfego pago',summary.ads,`${ads.length} aporte(s) em anúncios`]];
 const lines=[['Vendas do mês',summary.gross],['− Taxas da maquininha',summary.fees],['− Parceiros por curso',summary.partners],['− Gastos fixos',summary.fixed],['− Gastos variáveis',summary.variable],['− Aportes em anúncios',summary.ads]];
 section.innerHTML=`<div class="finance-heading">${tab==='overview'?`<div><div class="eyebrow">RESULTADO MENSAL</div><h2>${esc(monthLabel(financeMonth))}</h2></div>`:'<div></div>'}<label class="month-picker">Mês de referência<input id="finance-month" type="month" min="1900-01" max="9999-12" value="${financeMonth}" required></label></div>
 <div class="stats finance-stats">${cards.map((c,i)=>`<article class="stat ${tab==='overview'&&i===3?'result-stat':''} ${tab==='overview'&&i===3&&c[1]<0?'red':''}"><div class="stat-top">${c[0]}</div><div class="stat-value">${money(c[1])}</div><p class="stat-caption">${c[2]}</p></article>`).join('')}</div>
 ${tab==='overview'?receiptsOverview():''}
 ${tab==='overview'?`<div class="financial-basis"><strong>Resultado final das vendas do mês, após custos e imposto informado.</strong><p>O imposto é calculado sobre o faturamento bruto das vendas. O resultado usa as vendas pela data do cadastro, mesmo quando parceladas, e não representa necessariamente o saldo em caixa.</p>${summary.examples?`<p class="finance-alert">${summary.examples} gasto(s) de exemplo não entram no cálculo. Edite e salve com os valores reais.</p>`:''}${!expenses.some(r=>!r.example)?'<p class="finance-alert">Nenhum gasto confirmado neste mês. Cadastre ou copie os gastos do mês anterior para completar o resultado.</p>':''}</div>`:''}
 ${tab==='overview'?`<div class="panel finance-breakdown"><div class="panel-heading"><div><h2>Como chegamos ao resultado</h2><p>Custos, tráfego e imposto são descontados do faturamento do mês.</p></div><button class="secondary" data-finance-export>↓ Exportar resultado</button></div><div class="breakdown-lines">${lines.map(([name,value])=>`<div><span>${name}</span><strong>${money(value)}</strong></div>`).join('')}<div class="tax-line"><label>− Imposto sobre o faturamento <span><input id="tax-rate" type="number" min="0" max="100" step="0.01" value="${summary.taxRate}">%</span></label><strong>${money(summary.tax)}</strong></div><div class="breakdown-total"><strong>Resultado final do mês</strong><strong>${money(summary.net)}</strong></div></div></div>`:tab==='expenses'?expenseTable(expenses):adTable(ads)}`;
 if(tab==='expenses')section.querySelector('section.panel')?.classList.add('expense-table');
 $('#finance-month').onchange=e=>{if(validMonth(e.target.value)){financeMonth=e.target.value;render()}else e.target.reportValidity()};
 $('#tax-rate')?.addEventListener('change',e=>{const rate=Number(e.target.value);if(!Number.isFinite(rate)||rate<0||rate>100)return toast('Informe um imposto entre 0% e 100%.');commit({...state,taxRates:{...(state.taxRates||{}),[financeMonth]:rate}});toast('Imposto do mês atualizado.')});
 section.querySelector('[data-finance-export]')?.addEventListener('click',exportFinance);
 section.querySelector('[data-copy-expenses]')?.addEventListener('click',copyExpenses);
 section.querySelector('[data-expense-examples]')?.addEventListener('click',()=>{const additions=expenseExamples().map(r=>({...r,month:financeMonth})).filter(r=>!state.expenses.some(x=>x.month===financeMonth&&x.recurringKey===r.recurringKey));if(!additions.length)return toast('Os modelos já estão neste mês.');commit({...state,expenses:[...state.expenses,...additions]})});
 section.querySelectorAll('[data-expense-edit]').forEach(b=>b.onclick=()=>openExpense(b.dataset.expenseEdit));
 section.querySelectorAll('[data-ad-edit]').forEach(b=>b.onclick=()=>openAd(b.dataset.adEdit));
}
function expenseStatus(r){if(r.example)return ['soon','Exemplo'];if(r.paidDate)return ['delivered','Pago'];if(r.dueDate&&r.dueDate<today())return ['late','Atrasado'];return ['pending','Pendente']}
function expenseTable(rows){return `<section class="panel"><div class="panel-heading"><div><h2>Gastos mensais de ${esc(monthLabel(financeMonth))}</h2><p>Separe os compromissos fixos dos gastos que variam a cada mês.</p></div><div class="finance-actions"><button class="secondary" data-copy-expenses>↻ Copiar mês anterior</button><button class="secondary" data-finance-export>↓ Exportar</button></div></div><div class="table-scroll"><table><thead><tr><th>Descrição</th><th>Tipo</th><th>Vencimento</th><th>Pagamento</th><th>Valor + juros</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(r=>{const s=expenseStatus(r),total=r.amount+(r.interest??0);return `<tr><td><strong>${esc(r.name)}</strong><span class="sub">${expenseCategories[r.category]} • ${esc(r.recipient)||'Sem fornecedor'}</span></td><td>${expenseTypes[r.expenseType??'fixed']}</td><td>${date(r.dueDate)}</td><td>${date(r.paidDate)}</td><td>${r.example&&r.category==='marketing'&&r.amount===0?'A informar':`${money(total)}${r.interest?`<span class="sub">Inclui ${money(r.interest)} de juros</span>`:''}`}</td><td><span class="badge ${s[0]}">${s[1]}</span></td><td><button class="row-button" data-expense-edit="${esc(r.id)}">${r.example?'Definir valor':'Editar'}</button></td></tr>`}).join(''):'<tr><td colspan="7" class="empty">Nenhum gasto mensal neste período. Cadastre um gasto ou copie o mês anterior.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${rows.filter(r=>!r.example).length} gasto(s) contabilizado(s)</span><button class="text-button" data-expense-examples>Adicionar modelos: Marketing e Érico</button></div></section>`}
function adTable(rows){return `<section class="panel"><div class="panel-heading"><div><h2>Aportes em anúncios</h2><p>Cada R$ 100, R$ 200 ou outro valor colocado na plataforma fica registrado aqui.</p></div><button class="secondary" data-finance-export>↓ Exportar</button></div><div class="table-scroll"><table><thead><tr><th>Data do aporte</th><th>Plataforma</th><th>Observação</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${date(r.date)}</td><td><strong>${esc(r.platform)}</strong></td><td class="finance-note-cell">${esc(r.note)||'—'}</td><td>${money(r.amount)}</td><td><button class="row-button" data-ad-edit="${esc(r.id)}">Editar</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Nenhum aporte neste mês. Use “Novo aporte” a cada valor colocado nos anúncios.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${rows.length} aporte(s) neste mês</span><span>Não inclui o pagamento mensal do gestor de marketing.</span></div></section>`}
function copyExpenses(){
 const additions=repeatExpenses(state.expenses,financeMonth,()=>crypto.randomUUID());
 if(!additions.length)return toast('Nenhum gasto confirmado do mês anterior está faltando neste mês.');
 if(confirm(`Copiar ${additions.length} gasto(s) fixo(s) do mês anterior para ${monthLabel(financeMonth)}? Confira os valores após copiar.`)&&commit({...state,expenses:[...state.expenses,...additions]}))toast('Gastos copiados. O histórico anterior foi preservado.');
}
const expenseForm=$('#expense-form'),adForm=$('#ad-form');
function openExpense(id){
 expenseForm.reset();const r=state.expenses.find(r=>r.id===id);expenseForm.elements.id.value='';expenseForm.elements.month.value=financeMonth;
 if(r)Object.entries(r).forEach(([k,v])=>{if(expenseForm.elements[k])expenseForm.elements[k].value=v});
 if(!r)expenseForm.elements.dueDate.value=today().slice(0,7)===financeMonth?today():financeMonth+'-01';
 if(r?.example&&r.category==='marketing'&&r.amount===0)expenseForm.elements.amount.value='';
 else expenseForm.elements.amount.value=money(r?.amount||0);
 expenseForm.elements.interest.value=money(r?.interest||0);
 $('#expense-title').textContent=r?'Editar gasto mensal':'Novo gasto mensal';$('#expense-example-note').hidden=!r?.example;$('#delete-expense').hidden=!r;$('#expense-dialog').showModal();
}
function openAd(id){
 adForm.reset();const r=state.adSpends.find(r=>r.id===id);adForm.elements.id.value='';adForm.elements.date.value=today().slice(0,7)===financeMonth?today():financeMonth+'-01';
 if(r)Object.entries(r).forEach(([k,v])=>{if(adForm.elements[k])adForm.elements[k].value=v});
 adForm.elements.amount.value=money(r?.amount||0);
 $('#ad-title').textContent=r?'Editar aporte de tráfego':'Novo aporte de tráfego';$('#delete-ad').hidden=!r;$('#ad-dialog').showModal();
}
$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
expenseForm.elements.amount.oninput=()=>maskMoneyInput(expenseForm.elements.amount);
expenseForm.elements.interest.oninput=()=>maskMoneyInput(expenseForm.elements.interest);
adForm.elements.amount.oninput=()=>maskMoneyInput(adForm.elements.amount);
expenseForm.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(expenseForm)),old=state.expenses.find(r=>r.id===values.id);const r={...values,id:old?.id||crypto.randomUUID(),recurringKey:old?.recurringKey||crypto.randomUUID(),name:values.name.trim(),recipient:values.recipient.trim(),amount:parseBRL(values.amount),interest:parseBRL(values.interest),example:false};if(!validExpense(r))return toast('Confira mês, vencimento, descrição, valor e juros do gasto.');if(state.expenses.some(x=>x.id!==r.id&&x.month===r.month&&x.recurringKey===r.recurringKey))return toast('Este gasto recorrente já existe no mês escolhido. Edite o lançamento daquele mês.');const expenses=old?state.expenses.map(x=>x.id===r.id?r:x):[...state.expenses,r];const previous=financeMonth;financeMonth=r.month;if(commit({...state,expenses})){$('#expense-dialog').close();toast('Gasto salvo e descontado do resultado mensal.')}else financeMonth=previous};
adForm.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(adForm)),old=state.adSpends.find(r=>r.id===values.id);const r={...values,id:old?.id||crypto.randomUUID(),platform:values.platform.trim(),note:values.note.trim(),amount:parseBRL(values.amount)};if(!validAd(r))return toast('Confira a data, a plataforma e o valor do aporte.');const adSpends=old?state.adSpends.map(x=>x.id===r.id?r:x):[...state.adSpends,r];const previous=financeMonth;financeMonth=r.date.slice(0,7);if(commit({...state,adSpends})){$('#ad-dialog').close();toast('Aporte salvo e descontado do resultado mensal.')}else financeMonth=previous};
$('#delete-expense').onclick=()=>{if(confirm('Excluir este gasto apenas deste mês?')&&commit({...state,expenses:state.expenses.filter(r=>r.id!==expenseForm.elements.id.value)})){$('#expense-dialog').close();toast('Gasto excluído deste mês.')}};
$('#delete-ad').onclick=()=>{if(confirm('Excluir este aporte de tráfego?')&&commit({...state,adSpends:state.adSpends.filter(r=>r.id!==adForm.elements.id.value)})){$('#ad-dialog').close();toast('Aporte excluído.')}};
function exportFinance(){
 let header,rows;const amount=v=>v.toFixed(2).replace('.',',');
 if(tab==='expenses'){header=['Mês','Descrição','Tipo','Categoria','Pago a','Vencimento','Data paga','Valor original','Juros ou multa','Valor total','Situação'];rows=state.expenses.filter(r=>r.month===financeMonth).map(r=>[r.month,r.name,expenseTypes[r.expenseType??'fixed'],expenseCategories[r.category],r.recipient,date(r.dueDate),date(r.paidDate),amount(r.amount),amount(r.interest??0),amount(r.amount+(r.interest??0)),expenseStatus(r)[1]])}
 else if(tab==='ads'){header=['Data do aporte','Plataforma','Observação','Valor'];rows=state.adSpends.filter(r=>r.date.slice(0,7)===financeMonth).map(r=>[date(r.date),r.platform,r.note,amount(r.amount)])}
 else{const t=monthlyTotals(state,financeMonth);header=['Mês','Vendas','Taxas maquininha','Parceiros por curso','Gastos fixos','Gastos variáveis','Tráfego pago','Imposto (%)','Imposto (R$)','Resultado final','Critério'];rows=[[financeMonth,...['gross','fees','partners','fixed','variable','ads'].map(k=>amount(t[k])),String(t.taxRate).replace('.',','),amount(t.tax),amount(t.net),'Imposto sobre faturamento bruto; vendas pela data; não representa saldo recebido. Exemplos excluídos.']]}
 const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[header,...rows].map(r=>r.map(cell).join(';')).join('\r\n'),`educacademico-${tab}-${financeMonth}.csv`,'text/csv;charset=utf-8');toast('Planilha do mês exportada.');
}
